'use strict';
const H={};
const p={"arm":6,"gripper":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 区分几何描述和语义分组
Object.assign(s, ((s,p)=>({arm:p.arm,gripper:p.gripper}))(s, p));
// 计算整个机器人自由度
Object.assign(s, ((s,p)=>({robotDof:s.arm+s.gripper}))(s, p));
// 按规划组选择状态空间
Object.assign(s, ((s,p)=>({planningDof:s.arm,excludedGripper:s.gripper}))(s, p));
// 核对状态消息长度
Object.assign(s, ((s,p)=>({expectedArmPositions:s.planningDof,modelCheck:'仅自由度记账'}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"target":1.5,"velocity":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 固定关节与约束
Object.assign(s, ((s,p)=>({lower:-1,upper:1,vmax:.8}))(s, p));
// 分别检查位置和速度
Object.assign(s, ((s,p)=>({positionValid:p.target>=s.lower&&p.target<=s.upper,velocityValid:p.velocity<=s.vmax}))(s, p));
// 给出明确的请求状态
Object.assign(s, ((s,p)=>({requestValid:s.positionValid&&s.velocityValid}))(s, p));
// 计算速度上限下的时间下界
Object.assign(s, ((s,p)=>({lowerBound:Math.abs(p.target)/s.vmax,canReachRequested:s.requestValid}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"desired":0.2,"jacobian":0.5,"damping":0.1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 把任务速度映射到关节空间
Object.assign(s, ((s,p)=>({jacobian:p.jacobian,desired:p.desired}))(s, p));
// 构造阻尼逆
Object.assign(s, ((s,p)=>({inverse:p.jacobian/(p.jacobian*p.jacobian+p.damping*p.damping)}))(s, p));
// 求关节速度与实际任务速度
Object.assign(s, ((s,p)=>({qdot:s.inverse*p.desired,achieved:p.jacobian*s.inverse*p.desired}))(s, p));
// 回算残差并检查限速
Object.assign(s, ((s,p)=>({residual:s.achieved-p.desired,withinLimit:Math.abs(s.qdot)<=1}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={dist:(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]),
segmentDistance:(a,b,c)=>{const dx=b[0]-a[0],dy=b[1]-a[1],den=dx*dx+dy*dy,t=den?Math.max(0,Math.min(1,((c[0]-a[0])*dx+(c[1]-a[1])*dy)/den)):0;return Math.hypot(a[0]+t*dx-c[0],a[1]+t*dy-c[1]);}};
const p={"obstacle":1,"radius":0.2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 给出一段机器人路径
Object.assign(s, ((s,p)=>({start:[0,0],goal:[2,0],center:[p.obstacle,.2]}))(s, p));
// 比较端点和整段距离
Object.assign(s, ((s,p)=>({endpointDistances:[H.dist(s.start,s.center),H.dist(s.goal,s.center)],segmentDistance:H.segmentDistance(s.start,s.goal,s.center)}))(s, p));
// 按接触也算碰撞判定
Object.assign(s, ((s,p)=>({endpointClear:s.endpointDistances.every(x=>x>p.radius),edgeClear:s.segmentDistance>p.radius}))(s, p));
// 保留场景版本的概念
Object.assign(s, ((s,p)=>({collisionFree:s.edgeClear,minimumClearance:s.segmentDistance-p.radius}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"step":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 定义一维配置空间的窄障碍
Object.assign(s, ((s,p)=>({invalidInterval:[.9,1.1],start:0,goal:2}))(s, p));
// 生成离散检查点
Object.assign(s, ((s,p)=>({samples:Array.from({length:Math.ceil(2/p.step)+1},(_,i)=>Math.min(2,i*p.step))}))(s, p));
// 分别做离散和连续检查
Object.assign(s, ((s,p)=>({discreteClear:!s.samples.some(x=>x>=.9&&x<=1.1),continuousClear:false}))(s, p));
// 用移位障碍展示漏检反例
Object.assign(s, ((s,p)=>({shiftedDiscreteClear:!s.samples.some(x=>x>=.4&&x<=.6),shiftedContinuousClear:false}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0)};
const p={"completed":3,"required":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 给出四段笛卡尔路径
Object.assign(s, ((s,p)=>({lengths:[1,1,2,2]}))(s, p));
// 分别计段数和弧长覆盖
Object.assign(s, ((s,p)=>({segmentFraction:p.completed/4,lengthFraction:H.sum(s.lengths.slice(0,p.completed))/H.sum(s.lengths)}))(s, p));
// 按本例弧长规则核对完整性
Object.assign(s, ((s,p)=>({accepted:s.lengthFraction>=p.required}))(s, p));
// 给出缺失路径长度
Object.assign(s, ((s,p)=>({remainingLength:H.sum(s.lengths.slice(p.completed)),fullPath:p.completed===4}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"distance":1,"vmax":1,"amax":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先固定单关节运动边界
Object.assign(s, ((s,p)=>({rampDistance:p.vmax*p.vmax/p.amax}))(s, p));
// 决定三角形还是梯形速度曲线
Object.assign(s, ((s,p)=>({triangular:p.distance<=s.rampDistance}))(s, p));
// 计算加速段和匀速段时间
Object.assign(s, ((s,p)=>({rampTime:s.triangular?Math.sqrt(p.distance/p.amax):p.vmax/p.amax,cruiseTime:s.triangular?0:(p.distance-s.rampDistance)/p.vmax}))(s, p));
// 合成总时长和峰值速度
Object.assign(s, ((s,p)=>({duration:2*s.rampTime+s.cruiseTime,peakVelocity:p.amax*s.rampTime}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"startError":0.02,"scene":"same","result":"success"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 规划结果先作为候选
Object.assign(s, ((s,p)=>({planned:true,sceneVersion:'v1'}))(s, p));
// 核对起点和场景
Object.assign(s, ((s,p)=>({startCompatible:p.startError<=.04,sceneCurrent:p.scene==='same'}))(s, p));
// 只在条件满足时请求执行
Object.assign(s, ((s,p)=>({requested:s.startCompatible&&s.sceneCurrent}))(s, p));
// 区分已请求与已成功
Object.assign(s, ((s,p)=>({success:s.requested&&p.result==='success',outcome:!s.requested?'未提交':p.result==='success'?'本例返回成功':'本例返回中止'}))(s, p));
console.log(JSON.stringify(s,null,2));
